import{_ as p,a0 as o,w as r,s as d,I as t,x as a,a1 as i,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密碼 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密碼 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密碼 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170308 How to Reset MySQL or MariaDB Root Password in Linux","title":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密碼","tag":"201703","desc":""},"relativePath":"201703/20170308 How to Reset MySQL or MariaDB Root Password in Linux.md","filePath":"[post].md"}'),m={name:"201703/20170308 How to Reset MySQL or MariaDB Root Password in Linux.md"};function u(g,s,b,y,h,k){const n=o("Link");return r(),d("div",null,[s[18]||(s[18]=t("h1",{id:"如何在-linux-中重置-mysql-或者-mariadb-的-root-密碼",tabindex:"-1"},[a("如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密碼 "),t("a",{class:"header-anchor",href:"#如何在-linux-中重置-mysql-或者-mariadb-的-root-密碼","aria-label":"Permalink to “如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密碼”"},"​")],-1)),s[19]||(s[19]=t("p",null,[a("如果你是第一次設置 MySQL 或 MariaDB 資料庫，你可以直接運行 "),t("code",null,"mysql_secure_installation"),a(" 來實現基本的安全設置。")],-1)),s[20]||(s[20]=t("p",null,"其中一項是設置資料庫 root 帳户的密碼 - 你必須保持私密，並僅在絕對需要時使用。如果你忘記了密碼或需要重置密碼（例如，當資料庫管理員換人或被裁員！），這篇文章會派上用場。我們將解釋如何在 Linux 中重置或恢復 MySQL 或 MariaDB 的 root 密碼。",-1)),t("p",null,[s[1]||(s[1]=t("strong",null,"建議閲讀：",-1)),s[2]||(s[2]=a(" [更改 MySQL 或 MariaDB 的 root 密碼] ",-1)),i(n,{href:"http://www.tecmint.com/change-mysql-mariadb-root-password/"},{default:e(()=>[...s[0]||(s[0]=[a("1",-1)])]),_:1}),s[3]||(s[3]=a("。",-1))]),s[21]||(s[21]=l(`<p>雖然我們將在本文中使用 MariaDB，但這些説明同樣也適用於 MySQL。</p><h3 id="恢復-mysql-或者-mariadb-的-root-密碼" tabindex="-1">恢復 MySQL 或者 MariaDB 的 root 密碼 <a class="header-anchor" href="#恢復-mysql-或者-mariadb-的-root-密碼" aria-label="Permalink to “恢復 MySQL 或者 MariaDB 的 root 密碼”">​</a></h3><p>開始之前，先停止資料庫服務並檢查服務狀態，我們應該可以看到先前設置的環境變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- SystemD ------------- </span></span>
<span class="line"><span># systemctl stop mariadb</span></span>
<span class="line"><span>------------- SysVinit -------------</span></span>
<span class="line"><span># /etc/init.d/mysqld stop</span></span></code></pre></div><p>接下來，用 <code>--skip-grant-tables</code> 選項啓動服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- SystemD ------------- </span></span>
<span class="line"><span># systemctl set-environment MYSQLD_OPTS=&quot;--skip-grant-tables&quot;</span></span>
<span class="line"><span># systemctl start mariadb</span></span>
<span class="line"><span># systemctl status mariadb</span></span>
<span class="line"><span>------------- SysVinit -------------</span></span>
<span class="line"><span># mysqld_safe --skip-grant-tables &amp;</span></span></code></pre></div>`,6)),t("p",null,[i(n,{href:"http://www.tecmint.com/wp-content/uploads/2017/03/Start-MySQL-with-Skip-Tables.png"},{default:e(()=>[...s[4]||(s[4]=[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/03/Start-MySQL-with-Skip-Tables.png",alt:"Start MySQL/MariaDB with Skip Tables"},null,-1)])]),_:1})]),s[22]||(s[22]=l(`<p><em>使用 skip tables 啓動 MySQL/MariaDB</em></p><p>這可以讓你不用 root 密碼就能連接到資料庫（你也許需要切換到另外一個終端上）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mysql -u root</span></span></code></pre></div><p>接下來，按照下面列出的步驟來。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MariaDB [(none)]&gt; USE mysql;</span></span>
<span class="line"><span>MariaDB [(none)]&gt; UPDATE user SET password=PASSWORD(&#39;YourNewPasswordHere&#39;) WHERE User=&#39;root&#39; AND Host = &#39;localhost&#39;;</span></span>
<span class="line"><span>MariaDB [(none)]&gt; FLUSH PRIVILEGES;</span></span></code></pre></div><p>最後，停止服務，取消環境變量設置並再次啓動服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- SystemD ------------- </span></span>
<span class="line"><span># systemctl stop mariadb</span></span>
<span class="line"><span># systemctl unset-environment MYSQLD_OPTS</span></span>
<span class="line"><span># systemctl start mariadb</span></span>
<span class="line"><span>------------- SysVinit -------------</span></span>
<span class="line"><span># /etc/init.d/mysql stop</span></span>
<span class="line"><span># /etc/init.d/mysql start</span></span></code></pre></div><p>這可以讓先前的改變生效，允許你使用新的密碼連接到資料庫。</p><h5 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h5><p>本文我們討論瞭如何重置 MariaDB/MySQL 的 root 密碼。一如往常，如果你有任何問題或反饋請在評論欄中給我們留言。我們期待聽到你的聲音。</p><hr><p>作者簡介：</p><p>Gabriel Cánepa - 一位來自阿根廷聖路易斯梅塞德斯鎮 (Villa Mercedes, San Luis, Argentina) 的 GNU/Linux 系統管理員，Web 開發者。就職於一家世界領先級的消費品公司，樂於在每天的工作中能使用 FOSS 工具來提高生產力。</p><hr>`,14)),t("p",null,[s[6]||(s[6]=a("via: ",-1)),i(n,{href:"http://www.tecmint.com/reset-mysql-or-mariadb-root-password/"},{default:e(()=>[...s[5]||(s[5]=[a("http://www.tecmint.com/reset-mysql-or-mariadb-root-password/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),i(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:e(()=>[...s[7]||(s[7]=[a("Gabriel Cánepa",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[8]||(s[8]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),i(n,{href:"https://github.com/jasminepeng"},{default:e(()=>[...s[9]||(s[9]=[a("jasminepeng",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const f=p(m,[["render",u]]);export{L as __pageData,f as default};
